<?php
declare(strict_types=1);namespace App\Interfaces\Http\Controllers\Api\V1\Reconciliation;
use App\Application\Reconciliation\ReconciliationService;use App\Domain\Tenancy\TenantContext;use App\Models\{ReconciliationImport,ReconciliationItem};use Illuminate\Http\{JsonResponse,Request};
final class ReconciliationController{private function scoped(string$id):ReconciliationImport{return ReconciliationImport::where(fn($q)=>$q->where('tenant_id',app(TenantContext::class)->id())->orWhereNull('tenant_id'))->findOrFail($id);}public function import(Request$r,ReconciliationService$s,TenantContext$c):JsonResponse{$d=$r->validate(['source_type'=>'required|in:PAYMENT_PROVIDER,CARRIER_BANK','provider'=>'required|string|max:40','statement_reference'=>'required|string|max:120','period_start'=>'required|date','period_end'=>'required|date|after_or_equal:period_start','currency'=>'required|in:XAF','file_hash'=>'required|size:64','items'=>'required|array|min:1|max:5000','items.*.external_reference'=>'required|string|max:160','items.*.transaction_at'=>'required|date','items.*.gross_minor'=>'required|integer|min:0','items.*.fee_minor'=>'required|integer|min:0','items.*.net_minor'=>'required|integer|min:0']);return response()->json(['data'=>$s->import($c->id(),$d,$r->user())],201);}public function show(string$import):JsonResponse{return response()->json(['data'=>$this->scoped($import)->load('items')]);}public function resolve(Request$r,string$item,ReconciliationService$s):JsonResponse{$d=$r->validate(['resolution'=>'required|in:MATCHED,IGNORED,ADJUSTMENT_REQUIRED','matched_type'=>'nullable|string|max:64','matched_id'=>'nullable|uuid','notes'=>'required|string|min:20|max:2000']);$i=ReconciliationItem::whereHas('import',fn($q)=>$q->where('tenant_id',app(TenantContext::class)->id()))->findOrFail($item);return response()->json(['data'=>$s->resolve($i,$d,$r->user())]);}public function approve(Request$r,string$import,ReconciliationService$s):JsonResponse{return response()->json(['data'=>$s->approve($this->scoped($import),$r->user())]);}}
